-- 0076_assist_activity: a matter's last activity and what its plan saw (ASSIST specs 8.5 F1/F2).
-- touched_at = the newest thing that happened on the matter (a message or act in its thread, a
-- changed version of its task); plan_seen_at = the touched_at the plan was made from. A plan is
-- made again only when touched_at moves past plan_seen_at; the plan queue runs newest touch
-- first; a matter with no activity since its due date is shown as "still open?". The list's view
-- gains touched_at (appended; grants stay). Additive. Undo: re-apply 0073's view, then
-- ALTER TABLE assist.matters DROP COLUMN touched_at, DROP COLUMN plan_seen_at.
ALTER TABLE assist.matters ADD COLUMN IF NOT EXISTS touched_at timestamptz;
ALTER TABLE assist.matters ADD COLUMN IF NOT EXISTS plan_seen_at timestamptz;
CREATE INDEX IF NOT EXISTS matters_plan_queue ON assist.matters (touched_at DESC) WHERE state = 'open' AND plan_status = 'none';
DO $view$ BEGIN IF to_regclass('biz.emails') IS NOT NULL AND to_regclass('biz.teams_messages') IS NOT NULL THEN EXECUTE $q$CREATE OR REPLACE VIEW assist.matter_items AS SELECT m.matter_id, m.owner_person, m.kind, m.subject_key, m.sources, m.basis_at, m.title, m.detail, m.next_act, m.due_at, m.state, m.verified_at, m.verify_note, m.plan, m.plan_status, m.plan_reason, m.audiences, m.markings, m.counterpart, m.legacy_item_id, m.opened_at, coalesce((SELECT array_agg(DISTINCT h) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(m.sources->'readings') = 'array' THEN m.sources->'readings' ELSE '[]'::jsonb END) s JOIN assist.readings r ON r.source = s->>0 AND r.message_key = s->>1, unnest(r.handles) h), '{}') AS handles, b.source, b.quote, e.sender, e.subject, t.sender AS tsender, m.plan_at, (SELECT max(l.at) FROM assist.matter_log l WHERE l.matter_id = m.matter_id AND l.what = 'requested') AS requested_at, m.touched_at FROM assist.matters m LEFT JOIN assist.readings b ON jsonb_typeof(m.sources->'readings') = 'array' AND b.source = m.sources->'readings'->-1->>0 AND b.message_key = m.sources->'readings'->-1->>1 LEFT JOIN LATERAL (SELECT x.sender, x.subject FROM biz.emails x WHERE b.source = 'emails' AND x.handle = b.handles[1] LIMIT 1) e ON true LEFT JOIN LATERAL (SELECT y.sender FROM biz.teams_messages y WHERE b.source = 'teams_messages' AND y.handle = b.handles[1] LIMIT 1) t ON true WHERE m.state IN ('open', 'unverified')$q$; ELSE EXECUTE $q$CREATE OR REPLACE VIEW assist.matter_items AS SELECT m.matter_id, m.owner_person, m.kind, m.subject_key, m.sources, m.basis_at, m.title, m.detail, m.next_act, m.due_at, m.state, m.verified_at, m.verify_note, m.plan, m.plan_status, m.plan_reason, m.audiences, m.markings, m.counterpart, m.legacy_item_id, m.opened_at, coalesce((SELECT array_agg(DISTINCT h) FROM jsonb_array_elements(CASE WHEN jsonb_typeof(m.sources->'readings') = 'array' THEN m.sources->'readings' ELSE '[]'::jsonb END) s JOIN assist.readings r ON r.source = s->>0 AND r.message_key = s->>1, unnest(r.handles) h), '{}') AS handles, b.source, b.quote, NULL::text AS sender, NULL::text AS subject, NULL::text AS tsender, m.plan_at, (SELECT max(l.at) FROM assist.matter_log l WHERE l.matter_id = m.matter_id AND l.what = 'requested') AS requested_at, m.touched_at FROM assist.matters m LEFT JOIN assist.readings b ON jsonb_typeof(m.sources->'readings') = 'array' AND b.source = m.sources->'readings'->-1->>0 AND b.message_key = m.sources->'readings'->-1->>1 WHERE m.state IN ('open', 'unverified')$q$; END IF; END $view$;
